<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {nativeCall,asAppError} from '@/platform/native'
import {useFileSourcesStore} from '@/stores/fileSources'
import type {Account} from './contracts'
import {t,useLocale} from '@/features/files/electron/i18n'
import ServerEndpoints from '@/features/servers/ServerEndpoints.vue'
import ElectronModal from '@/components/dialog/ElectronModal.vue'
import MediaServerSpeedTestModal from '@/features/files/electron/MediaServerSpeedTestModal.vue'
const props=defineProps<{account:Account}>(),emit=defineEmits<{saved:[];removed:[]}>(),sources=useFileSourcesStore()
const name=ref(props.account.name),address=ref(props.account.baseUrl),username=ref(''),password=ref(''),rootPath=ref('/'),busy=ref(false),loading=ref(true),error=ref(''),removing=ref(false),endpoints=ref(false),testing=ref(false),status=ref('')
const locale=useLocale(),endpointLabel=computed(()=>locale.value.startsWith('en')?'Edit Endpoint':'编辑端点')
const server=computed(()=>['jellyfin','emby','plex'].includes(props.account.providerId)),network=computed(()=>['webdav','smb','nfs','ftp'].includes(props.account.providerId)),requestId=crypto.randomUUID();let alive=true
onUnmounted(()=>{alive=false;password.value='';void nativeCall('auth_cancel',{requestId}).catch(()=>{})})
onMounted(async()=>{try{if(server.value||network.value){const info=await nativeCall<{username?:string;url?:string;rootPath?:string}>(server.value?'server_connection_info':props.account.providerId==='webdav'?'webdav_connection_info':'network_share_connection_info',{accountId:props.account.id});if(alive){username.value=info.username||'';address.value=info.url||props.account.baseUrl;rootPath.value=info.rootPath||'/'}}}catch(cause){error.value=asAppError(cause).message}finally{loading.value=false}})
async function save(){if(busy.value||loading.value)return;busy.value=true;error.value='';try{const accountId=props.account.id;if(server.value)await nativeCall('server_update_connection',{requestId,accountId,name:name.value,username:username.value,password:password.value||null});else if(network.value)await nativeCall(props.account.providerId==='webdav'?'webdav_update_connection':'network_share_update_connection',{accountId,name:name.value,url:address.value,username:username.value,password:password.value||null,rootPath:rootPath.value});else await nativeCall('account_update_metadata',{accountId,name:name.value,baseUrl:props.account.baseUrl});password.value='';await sources.refresh();if(alive)emit('saved')}catch(cause){error.value=asAppError(cause).message}finally{busy.value=false}}
async function remove(){if(busy.value)return;busy.value=true;try{await nativeCall('account_remove',{accountId:props.account.id});await sources.refresh();if(alive)emit('removed')}catch(cause){error.value=asAppError(cause).message}finally{busy.value=false}}
const speedServer=computed(()=>({id:props.account.id,type:props.account.providerId as 'emby'|'jellyfin'|'plex',name:props.account.name,baseUrl:props.account.baseUrl,createdAt:0,updatedAt:0}))
</script>
<template><section class="saved-editor"><header><h2>{{account.name}}</h2><button class="remove-share" type="button" :disabled="busy" @click="removing=true">{{t('mediaServer.removeShare')}}</button></header><form @submit.prevent="save"><label>{{t('mediaServer.name')}}<input v-model="name" :disabled="busy||loading" required/></label><label>{{t('mediaServer.protocol')}}<input :value="account.providerId" readonly/></label><label>{{t('mediaServer.host')}}<input v-model="address" :disabled="busy||loading" :readonly="!network"/></label><template v-if="server||network"><label>{{t('mediaServer.username')}}<input v-model="username" :disabled="busy||loading||account.providerId==='nfs'" autocomplete="username"/></label><label>{{t('mediaServer.password')}}<input v-model="password" :disabled="busy||loading" type="password" autocomplete="new-password" placeholder="••••••••"/></label><label v-if="network">{{t('mediaServer.path')}}<input v-model="rootPath" :disabled="busy||loading"/></label></template><p v-if="error" role="alert">{{error}}</p><p v-if="status" role="status">{{status}}</p><footer><button type="submit" :disabled="busy||loading" class="primary">{{t('common.save')}}</button><button v-if="server" type="button" :disabled="busy||loading" @click="testing=true">{{t('mediaServer.speedTest')}}</button><button v-if="server" type="button" :disabled="busy||loading" @click="endpoints=true">{{endpointLabel}}</button></footer></form><ServerEndpoints v-if="endpoints" :account="account" @close="endpoints=false"/><MediaServerSpeedTestModal v-if="testing" :visible="testing" :server="speedServer" @update:visible="testing=$event"/><ElectronModal v-if="removing" :title="t('mediaServer.removeShare')" :busy="busy" @close="removing=false"><p>{{account.name}}</p><template #footer><button type="button" :disabled="busy" @click="removing=false">{{t('common.cancel')}}</button><button type="button" :disabled="busy" @click="remove">{{t('common.confirm')}}</button></template></ElectronModal></section></template>
<style scoped>.saved-editor{height:100%;min-width:0;padding:0 24px;overflow:auto}.saved-editor header{position:relative;display:flex;justify-content:center;align-items:center;min-height:58px}.saved-editor h2{font-size:16px;text-align:center}.remove-share{position:absolute;right:0;top:12px;border:1px solid var(--control-border);border-radius:22px;background:var(--secondary);color:var(--foreground);padding:8px 14px}.saved-editor form{width:min(100%,540px);margin:36px auto}.saved-editor label{display:grid;grid-template-columns:110px minmax(0,1fr);gap:12px;align-items:center;margin:12px 0;font-size:14px;text-align:right}.saved-editor input{height:32px;min-width:0;width:100%;border:1px solid var(--control-border);border-radius:7px;background:var(--background);color:var(--foreground);padding:0 10px;font:inherit}.saved-editor footer{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);gap:8px;margin-top:28px}.saved-editor footer button{height:36px;border:1px solid var(--control-border);border-radius:7px;background:var(--secondary);color:var(--foreground);font:inherit;white-space:nowrap}.saved-editor footer .primary{background:var(--primary);color:white}.saved-editor [role=alert]{color:var(--destructive,#d43838)}.saved-editor button{cursor:pointer}.saved-editor button:disabled{opacity:.5}</style>
